for name,s in D.items():
 scope=f'[data-el="{K}-{name}"]'
 common='''&{box-sizing:border-box;min-width:0;min-height:0;color:var(--ink);font-family:var(--font-body);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);container-type:inline-size}& :where(p,h2,blockquote){margin:0}& :where(.name){font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}& .fig{font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}& .kick{font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);color:var(--a1-8)}& .note{font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}& .icon{display:block;width:32px;height:32px;flex:none}& small{color:inherit;margin:0}& .fig small{font-size:var(--type-20);line-height:var(--figure-line)}'''
 css=(common+s).replace('&',scope)
 default={}
 if name in ('cycle','hub'):
  member='node' if name=='cycle' else 'spoke';default={'--onboard-docket-i':'1','--onboard-docket-n':'4'}
  for n in range(3,7):css+=f'{scope}:has(>.{member}:nth-of-type({n+1}):last-child){{--onboard-docket-n:{n}}}'
  for i in range(1,7):css+=f'{scope}>.{member}:nth-of-type({i+1}){{--onboard-docket-i:{i}}}'
 if name=='pyramid':
  default={'--onboard-docket-width':'100%'}
  for n in range(3,6):
   for i in range(1,n+1):css+=f'{scope}:has(>.level:nth-child({n}):last-child)>.level:nth-child({i}){{--onboard-docket-width:{(i/n)*100:.3f}%}}'
 if name=='logo-group':default={'--onboard-docket-width':'22%'}
 if name=='concentric':
  default={'--onboard-docket-width':'100%'}
  for n in range(2,5):
   for i in range(1,n+1):css+=f'{scope}:has(>.ring:nth-child({n}):last-child)>.ring:nth-child({i}){{--onboard-docket-width:{100-(i-1)*65/n:.2f}%;z-index:{i}}}'
 if name=='agenda':
  default={'--onboard-docket-rows':'4'}
  for n in range(2,13):css+=f'{scope}:has(>.entry:nth-child({n}):last-child){{--onboard-docket-rows:{math.ceil(n/2)}}}'
 if name=='chart-line':
  default={'--onboard-docket-current':'--od-line-1'}
  for i in range(1,13):
   css+=f'{scope}>.pt:nth-child({i}){{--onboard-docket-current:--od-line-{i};anchor-name:--od-line-{i}}}'
   if i>=2:
    css+=f'{scope}>.pt:nth-child({i})::before{{left:anchor(--od-line-{i-1} center);right:anchor(--od-line-{i} center);top:anchor(--od-line-{i} center);bottom:anchor(--od-line-{i-1} center);background:linear-gradient(to bottom right,transparent calc(50% - 1px),var(--a1) calc(50% - 1px) calc(50% + 1px),transparent calc(50% + 1px))}}{scope}>.pt:nth-child({i})::after{{left:anchor(--od-line-{i-1} center);right:anchor(--od-line-{i} center);top:anchor(--od-line-{i-1} center);bottom:anchor(--od-line-{i} center);background:linear-gradient(to top right,transparent calc(50% - 1px),var(--a1) calc(50% - 1px) calc(50% + 1px),transparent calc(50% + 1px))}}'
 if name=='chart-area':
  for i in range(1,13):
   css+=f'{scope}>.series>.pt:nth-child({i} of .pt){{anchor-name:--od-area-{i}}}'
   if i==1:css+=f'{scope}>.series>.pt:nth-child(1 of .pt)::before,{scope}>.series>.pt:nth-child(1 of .pt)::after{{display:none}}'
   else:css+=f'{scope}>.series>.pt:nth-child({i} of .pt)::before,{scope}>.series>.pt:nth-child({i} of .pt)::after{{left:anchor(--od-area-{i-1} center);right:anchor(--od-area-{i} center);top:calc(anchor(--od-area-{i-1} top) - (100cqh - var(--gap-lg)*2))}}'
 if name=='radar':
  default={'--onboard-docket-i':'1'}
  for i in range(1,9):css+=f'{scope}>.axis:nth-child({i}){{--onboard-docket-i:{i}}}'
  for n in range(3,9):
   poly=','.join(f'calc(50% + sin({(i-1)*360/n:.5f}deg)*var(--v{i})/var(--max)*50%) calc(50% - cos({(i-1)*360/n:.5f}deg)*var(--v{i})/var(--max)*50%)' for i in range(1,n+1))
   css+=f'{scope}:has(>.axis:nth-child({n}):not(.series)):not(:has(>.axis:nth-child({n+1})))>.series::before{{clip-path:polygon({poly})}}'
 if name=='sankey':default['--onboard-docket-sankey-inset']='40%'
 if name=='journey':default['--onboard-docket-journey-inset']='45%'
 # Replace transparent masks using opacity stops; literal #000 only existed in donut mask and is prohibited.
 css=css.replace('mask:radial-gradient(circle, var(--page) 0 51%,var(--ink) 52%);-webkit-mask:radial-gradient(circle, #0000 0 51%,#000 52%)','mask:radial-gradient(circle, transparent 0 51%,var(--ink) 52%)')
 (C/'elements'/name/'element.css').write_text(css+'\n')
 meta=json.loads((C/'elements'/name/'element.json').read_text());meta['tokenDefaults']=default;(C/'elements'/name/'element.json').write_text(json.dumps(meta,indent=2)+'\n')
 (C/'elements'/name/'description.md').write_text(f'The {name.replace("-"," ")} belongs to the Onboard Docket document language. Quietly rounded neutral surfaces, capsule labels, circular markers and a single ranked accent maintain a stable reading order. Strong figures and names remain visible as the container narrows; supporting text steps down before it is removed. The form uses deliberate internal spacing and restrained hairlines rather than decorative texture.\n')
print('wrote',len(D),'element styles')
